/*
 * Self-contained offline Chart.js-compatible canvas renderer for local Jetson LAN use.
 * Supports responsive HiDPI 'line' and dual-axis 'bar' charts with zero internet dependencies.
 * To swap in upstream Chart.js when online, run: ./scripts/download_chartjs.sh
 */
(function (global) {
  "use strict";

  class OfflineChart {
    constructor(ctxOrCanvas, config) {
      this.ctx = ctxOrCanvas.getContext ? ctxOrCanvas.getContext("2d") : ctxOrCanvas;
      this.canvas = this.ctx.canvas;
      this.type = (config && config.type) || "line";
      this.data = (config && config.data) || { labels: [], datasets: [] };
      this.options = (config && config.options) || {};
      this._resizeBound = () => this.update("none");
      global.addEventListener("resize", this._resizeBound);
      this.update("none");
    }

    _syncSize() {
      const parent = this.canvas.parentElement;
      const dpr = global.devicePixelRatio || 1;
      const w = Math.max(240, parent ? parent.clientWidth : 480);
      const h = Math.max(180, parent ? parent.clientHeight : 240);
      if (this.canvas.width !== Math.round(w * dpr) || this.canvas.height !== Math.round(h * dpr)) {
        this.canvas.width = Math.round(w * dpr);
        this.canvas.height = Math.round(h * dpr);
        this.canvas.style.width = w + "px";
        this.canvas.style.height = h + "px";
      }
      this.ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
      return { w, h };
    }

    update() {
      const { w, h } = this._syncSize();
      const ctx = this.ctx;
      ctx.clearRect(0, 0, w, h);

      if (this.type === "bar") {
        this._drawBar(ctx, w, h);
      } else {
        this._drawLine(ctx, w, h);
      }
    }

    _drawLegend(ctx, w, datasets) {
      ctx.font = "12px -apple-system, BlinkMacSystemFont, 'Segoe UI', sans-serif";
      let x = w - 12;
      for (let i = datasets.length - 1; i >= 0; i--) {
        const ds = datasets[i];
        const label = ds.label || "";
        const tw = ctx.measureText(label).width;
        x -= tw;
        ctx.fillStyle = "#cbd5e1";
        ctx.textAlign = "left";
        ctx.fillText(label, x, 16);
        x -= 16;
        ctx.fillStyle = ds.borderColor || ds.backgroundColor || "#38bdf8";
        ctx.fillRect(x, 7, 10, 10);
        x -= 14;
      }
    }

    _drawLine(ctx, w, h) {
      const pad = { top: 28, right: 16, bottom: 20, left: 42 };
      const plotW = w - pad.left - pad.right;
      const plotH = h - pad.top - pad.bottom;
      const datasets = this.data.datasets || [];
      const yScale = (this.options.scales && this.options.scales.y) || {};
      const minY = typeof yScale.min === "number" ? yScale.min : 0;
      const maxY = typeof yScale.max === "number" ? yScale.max : 185;

      // Grid + Y-axis labels
      const steps = 4;
      ctx.font = "11px -apple-system, BlinkMacSystemFont, 'Segoe UI', sans-serif";
      ctx.textAlign = "right";
      ctx.textBaseline = "middle";
      for (let i = 0; i <= steps; i++) {
        const ratio = i / steps;
        const val = Math.round(maxY - ratio * (maxY - minY));
        const y = pad.top + ratio * plotH;
        ctx.strokeStyle = "rgba(148, 163, 184, 0.14)";
        ctx.lineWidth = 1;
        ctx.beginPath();
        ctx.moveTo(pad.left, y);
        ctx.lineTo(w - pad.right, y);
        ctx.stroke();
        ctx.fillStyle = "#94a3b8";
        ctx.fillText(String(val), pad.left - 8, y);
      }

      this._drawLegend(ctx, w, datasets);

      datasets.forEach((ds) => {
        const values = ds.data || [];
        if (values.length < 2) return;
        const pts = values.map((v, idx) => {
          const x = pad.left + (idx / Math.max(values.length - 1, 1)) * plotW;
          const clamped = Math.max(minY, Math.min(maxY, Number(v) || 0));
          const y = pad.top + ((maxY - clamped) / (maxY - minY)) * plotH;
          return { x, y };
        });

        if (ds.fill) {
          ctx.beginPath();
          ctx.moveTo(pts[0].x, pad.top + plotH);
          pts.forEach((p) => ctx.lineTo(p.x, p.y));
          ctx.lineTo(pts[pts.length - 1].x, pad.top + plotH);
          ctx.closePath();
          ctx.fillStyle = ds.backgroundColor || "rgba(56, 189, 248, 0.14)";
          ctx.fill();
        }

        ctx.beginPath();
        pts.forEach((p, idx) => {
          if (idx === 0) ctx.moveTo(p.x, p.y);
          else ctx.lineTo(p.x, p.y);
        });
        ctx.strokeStyle = ds.borderColor || "#38bdf8";
        ctx.lineWidth = ds.borderWidth || 2;
        ctx.stroke();
      });
    }

    _drawBar(ctx, w, h) {
      const pad = { top: 28, right: 38, bottom: 36, left: 38 };
      const plotW = w - pad.left - pad.right;
      const plotH = h - pad.top - pad.bottom;
      const labels = this.data.labels || [];
      const datasets = this.data.datasets || [];

      this._drawLegend(ctx, w, datasets);

      if (!labels.length) {
        ctx.fillStyle = "#64748b";
        ctx.font = "12px -apple-system, BlinkMacSystemFont, 'Segoe UI', sans-serif";
        ctx.textAlign = "center";
        ctx.fillText("Record a session to see performance comparison", w / 2, h / 2);
        return;
      }

      const ds0 = (datasets[0] && datasets[0].data) || [];
      const ds1 = (datasets[1] && datasets[1].data) || [];
      const maxLeft = Math.max(5, ...ds0.map((v) => Number(v) || 0));
      const maxRight = 100;

      // Grid + Dual Y-axis labels
      const steps = 4;
      ctx.font = "11px -apple-system, BlinkMacSystemFont, 'Segoe UI', sans-serif";
      ctx.textBaseline = "middle";
      for (let i = 0; i <= steps; i++) {
        const ratio = i / steps;
        const y = pad.top + ratio * plotH;
        ctx.strokeStyle = "rgba(148, 163, 184, 0.14)";
        ctx.lineWidth = 1;
        ctx.beginPath();
        ctx.moveTo(pad.left, y);
        ctx.lineTo(w - pad.right, y);
        ctx.stroke();

        ctx.textAlign = "right";
        ctx.fillStyle = "#4ade80";
        ctx.fillText(String(Math.round(maxLeft * (1 - ratio))), pad.left - 6, y);

        ctx.textAlign = "left";
        ctx.fillStyle = "#38bdf8";
        ctx.fillText(String(Math.round(maxRight * (1 - ratio))) + "%", w - pad.right + 6, y);
      }

      const groupW = plotW / labels.length;
      const barW = Math.min(24, Math.max(8, groupW * 0.3));

      labels.forEach((lbl, idx) => {
        const cx = pad.left + idx * groupW + groupW / 2;

        // Dataset 0 (Reps)
        const v0 = Number(ds0[idx]) || 0;
        const h0 = (v0 / maxLeft) * plotH;
        ctx.fillStyle = (datasets[0] && datasets[0].backgroundColor) || "#22c55e";
        ctx.fillRect(cx - barW - 2, pad.top + plotH - h0, barW, h0);

        // Dataset 1 (Consistency %)
        const v1 = Math.min(100, Math.max(0, Number(ds1[idx]) || 0));
        const h1 = (v1 / maxRight) * plotH;
        ctx.fillStyle = (datasets[1] && datasets[1].backgroundColor) || "#38bdf8";
        ctx.fillRect(cx + 2, pad.top + plotH - h1, barW, h1);

        // X label
        ctx.fillStyle = "#94a3b8";
        ctx.textAlign = "center";
        ctx.textBaseline = "top";
        const shortLbl = String(lbl).length > 12 ? String(lbl).slice(0, 11) + "…" : String(lbl);
        ctx.fillText(shortLbl, cx, pad.top + plotH + 8);
      });
    }
  }

  global.Chart = OfflineChart;
})(window);
